#!/usr/bin/env bash
set -euo pipefail

usage() {
  echo "usage: $0 LOGFILE|-" >&2
  exit 2
}

[ $# -eq 1 ] || usage
src=$1
if [ "$src" = "-" ]; then
  input=/dev/stdin
else
  [ -r "$src" ] || { echo "cannot read $src" >&2; exit 1; }
  input=$src
fi

awk '
  $2 == "ERROR" { e++ }
  $2 == "WARN"  { w++ }
  $2 == "INFO"  { i++ }
  END { printf "ERROR=%d WARN=%d INFO=%d\n", e, w, i }
' "$input"

reference.rotate.sh:
#!/usr/bin/env bash
set -euo pipefail

[ $# -eq 2 ] || { echo "usage: $0 DIR KEEP" >&2; exit 2; }
dir=$1
keep=$2
case $keep in
  '' | *[!0-9]*) echo "KEEP must be a non-negative integer" >&2; exit 2 ;;
esac
[ -d "$dir" ] || { echo "not a directory: $dir" >&2; exit 1; }

mapfile -t files < <(find "$dir" -maxdepth 1 -type f -name 'backup-*.tar.gz' -print | LC_ALL=C sort)
n=${#files[@]}
[ "$n" -gt "$keep" ] || exit 0

for f in "${files[@]:0:n-keep}"; do
  rm -f -- "$f"
  echo "deleted $(basename "$f")"
done

