#!/usr/bin/env bash
set -euo pipefail

usage() {
  echo "usage: $0 [-e ENV] [-n COUNT] [-v] [FILE]" >&2
  exit 2
}

env=dev
count=1
verbose=0
while getopts ":e:n:vh" opt; do
  case $opt in
    e) env=$OPTARG ;;
    n) count=$OPTARG ;;
    v) verbose=1 ;;
    h) usage ;;
    :) echo "option -$OPTARG requires an argument" >&2; usage ;;
    *) echo "unknown option -$OPTARG" >&2; usage ;;
  esac
done
shift $((OPTIND - 1))

case $count in
  '' | *[!0-9]*) echo "count must be numeric" >&2; usage ;;
esac

file=${1:-none}
echo "env=$env count=$count verbose=$verbose file=$file"

reference.bump.sh:
#!/usr/bin/env bash
set -euo pipefail

[ $# -eq 2 ] || { echo "usage: $0 major|minor|patch FILE" >&2; exit 2; }
level=$1
file=$2
case $level in
  major | minor | patch) ;;
  *) echo "unknown level: $level" >&2; exit 2 ;;
esac
[ -f "$file" ] || { echo "no such file: $file" >&2; exit 1; }

current=$(tr -d '[:space:]' < "$file")
re='^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'
if [[ ! $current =~ $re ]]; then
  echo "invalid version: $current" >&2
  exit 1
fi
major=${BASH_REMATCH[1]}
minor=${BASH_REMATCH[2]}
patch=${BASH_REMATCH[3]}

case $level in
  major) major=$((major + 1)); minor=0; patch=0 ;;
  minor) minor=$((minor + 1)); patch=0 ;;
  patch) patch=$((patch + 1)) ;;
esac
new="$major.$minor.$patch"
echo "$new" > "$file"
echo "$new"

reference.disk_alert.sh:
#!/usr/bin/env bash
set -euo pipefail

[ $# -eq 1 ] || { echo "usage: $0 THRESHOLD" >&2; exit 2; }
case $1 in
  '' | *[!0-9]*) echo "THRESHOLD must be an integer" >&2; exit 2 ;;
esac

alerts=$(df -P | awk -v t="$1" '
  NR > 1 {
    pct = $5
    sub(/%/, "", pct)
    if (pct + 0 > t) {
      mount = $6
      for (i = 7; i <= NF; i++) mount = mount " " $i
      print "ALERT " mount " " $5
    }
  }')

if [ -n "$alerts" ]; then
  echo "$alerts"
  exit 1
fi
echo "ok"

